def backfill_monthly_tariffs_and_ended_dates(apps, schema_editor):
    Course = apps.get_model('core', 'Course')
    Enrollment = apps.get_model('core', 'Enrollment')
    Resource = apps.get_model('core', 'Resource')

    for course in Course.objects.all().iterator():
        duration = max(course.duration_months or 0, 1)
        course.monthly_fee_amount = (
            course.fee_amount + duration // 2
        ) // duration
        course.save(update_fields=['monthly_fee_amount'])

    ended = Enrollment.objects.filter(
        status__in=['COMPLETED', 'CANCELLED', 'SUSPENDED'],
        ended_at__isnull=True,
    )
    for enrollment in ended.iterator():
        enrollment.ended_at = (
            enrollment.completed_at.date()
            if enrollment.completed_at else enrollment.updated_at.date()
        )
        enrollment.save(update_fields=['ended_at'])

    Resource.objects.filter(
        status='PUBLISHED', published_at__isnull=True,
    ).update(published_at=models.F('created_at'))


